from pathlib import Path
import json
import pandas as pd
root=Path(__file__).resolve().parent
src = pd.read_csv(root/'data/customers_scored.csv',encoding='utf-8-sig')
cols=['customer_id','tenure_months','monthly_transactions','avg_balance_million_vnd','app_login_days_30d','complaints_90d','product_count','digital_usage_pct','inactive_days','churn_next_30d','risk_score','pred_high_risk']
rows=src[cols].to_dict(orient='records')
params=json.loads((root/'results/model_parameters.json').read_text(encoding='utf-8'))
metrics=json.loads((root/'results/metrics.json').read_text(encoding='utf-8'))
html = r'''<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ChurnSense | AI Customer Churn Portfolio Demo</title>
<style>
:root{--navy:#14273a;--navy2:#203a50;--teal:#137f85;--teal2:#dff4f2;--bg:#f3f6f8;--ink:#203144;--muted:#63768a;--border:#e1e9ee;--warn:#b75528;--rose:#b93946;--white:white}
*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,system-ui,-apple-system,'Segoe UI',Arial,sans-serif;color:var(--ink)}
header{background:var(--navy);color:white;padding:20px max(24px,calc((100vw - 1280px)/2));display:flex;justify-content:space-between;align-items:center;gap:16px} .brand{display:flex;gap:12px;align-items:center}.brandmark{background:#22b4ad;width:42px;height:42px;border-radius:11px;display:grid;place-items:center;color:var(--navy);font-weight:900;font-size:19px}.brand h1{font-size:22px;letter-spacing:-.65px;margin:0}.brand small{color:#aac8cf;font-size:11px;letter-spacing:.07em;text-transform:uppercase}.head-meta{text-align:right;font-size:12px;color:#bed5db;line-height:1.7}
main{max-width:1280px;margin:30px auto 60px;padding:0 24px}.intro{display:flex;justify-content:space-between;align-items:end;gap:20px;flex-wrap:wrap}.eyebrow{color:var(--teal);text-transform:uppercase;letter-spacing:.14em;font-size:11px;font-weight:800}.intro h2{font-size:29px;letter-spacing:-1px;margin:8px 0}.intro p{color:var(--muted);font-size:14px;margin:0;max-width:760px;line-height:1.6}.pill{border-radius:40px;background:#e4f4ed;color:#287456;padding:9px 13px;font-weight:700;font-size:12px}
.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:25px 0 19px}.stat,.panel{background:var(--white);border:1px solid var(--border);border-radius:15px;box-shadow:0 5px 18px rgba(20,45,60,.035)}.stat{padding:20px 21px}.stat .k{color:var(--muted);font-size:12px;font-weight:600}.stat strong{font-size:29px;letter-spacing:-1px;display:block;margin:9px 0 4px}.stat small{font-size:11px;color:var(--muted)}.stat.accent strong{color:var(--teal)}.stat.red strong{color:var(--rose)}
.layout{display:grid;grid-template-columns:1.45fr 1fr;gap:16px}.panel{padding:22px}.panelhead{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:15px}.panel h3{margin:0;font-size:16px;letter-spacing:-.3px}.sub{font-size:12px;color:var(--muted);line-height:1.6}.bars{display:flex;height:190px;gap:10px;align-items:end;padding:19px 6px 0;border-bottom:1px solid var(--border)}.barcol{flex:1;height:100%;display:flex;flex-direction:column;justify-content:end;gap:7px;text-align:center;font-size:11px;color:var(--muted)}.bar{border-radius:7px 7px 0 0;background:linear-gradient(180deg,#3fbcb1,var(--teal));min-height:3px;transition:height .3s}.barcol:nth-child(n+4) .bar{background:linear-gradient(180deg,#edac91,#c65b48)}.barcol b{color:var(--ink);font-size:11px}
.impact{display:flex;flex-direction:column;gap:14px;padding-top:4px}.impactrow{display:grid;grid-template-columns:176px 1fr 75px;align-items:center;gap:10px;font-size:11.5px}.impactrow .name{color:var(--ink)}.track{background:#edf2f5;border-radius:5px;height:10px;overflow:hidden}.fill{height:10px;border-radius:5px;background:#218b91}.fill.plus{background:#e16d61}.impactrow small{text-align:right;color:var(--muted)}.footnote{color:var(--muted);font-size:11px;margin-top:17px;line-height:1.65}
.scenario{margin-top:17px}.formgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px 18px}.field{min-width:0}.fieldlabel{display:flex;justify-content:space-between;align-items:center;gap:4px;color:var(--ink);font-size:12px;margin-bottom:5px}.fieldval{color:var(--teal);font-size:12px;font-weight:750}input[type=range]{width:100%;accent-color:var(--teal);cursor:pointer}.scen-bottom{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;background:#f8fbfc;padding:16px;margin-top:18px;border:1px solid var(--border);border-radius:11px}.scoreline{display:flex;align-items:center;gap:18px}.meter{width:125px;background:#e4ebef;border-radius:99px;height:13px;overflow:hidden}.meter span{display:block;height:100%;background:#118b82;border-radius:99px}.scorebig{font-size:29px;line-height:1.1;font-weight:850;letter-spacing:-.8px}.level{font-size:12px;color:var(--muted);margin-top:3px}.actions{display:flex;gap:10px;align-items:center}button{border:0;background:var(--navy2);color:white;padding:10px 15px;border-radius:8px;font:700 12px inherit;cursor:pointer}button.alt{background:var(--teal2);color:#13797b}button:hover{filter:brightness(1.1)}
.tablepanel{margin-top:17px}.tablehead{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px}.filters{display:flex;flex-wrap:wrap;gap:8px;align-items:center}input[type=search],select{padding:10px 12px;border:1px solid #d4e2e9;background:white;border-radius:8px;font-size:12px;color:var(--ink)}input[type=search]{width:200px}table{border-collapse:collapse;width:100%;font-size:12px}th{text-align:left;color:var(--muted);font-size:11px;font-weight:700;border-bottom:1px solid var(--border);padding:12px 10px;background:#f8fafb}td{border-bottom:1px solid #f0f2f5;padding:11px 10px;color:#35465b}th:last-child,td:last-child{text-align:right}tbody tr:hover{background:#f7fbfc}.tag{border-radius:30px;display:inline-block;padding:5px 9px;font-size:11px;font-weight:650}.tag.high{color:#b23f3e;background:#fff0ed}.tag.low{color:#21826d;background:#e8f6ef}.barcell{width:100px;max-width:160px}.barbg{background:#e9f0f1;height:7px;border-radius:7px;overflow:hidden}.barbg span{height:100%;display:block;border-radius:7px;background:var(--teal)}.barbg span.high{background:#d35b53}.scroll{overflow-x:auto}.below{color:var(--muted);font-size:11px;display:flex;justify-content:space-between;gap:10px;margin-top:12px;line-height:1.55}.alert{background:#fff8e9;border:1px solid #fae7b9;border-radius:10px;padding:13px 16px;margin-top:17px;color:#715523;font-size:12px;line-height:1.7}
footer{margin-top:24px;color:#7c8a9b;font-size:11px;line-height:1.6}
@media(max-width:950px){.cards{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:1fr}.formgrid{grid-template-columns:repeat(2,1fr)}.impactrow{grid-template-columns:160px 1fr 70px}}@media(max-width:570px){header{padding:15px}.head-meta{display:none}main{padding:0 12px;margin:20px auto}.intro h2{font-size:24px}.cards{gap:8px}.stat{padding:13px}.stat strong{font-size:23px}.panel{padding:15px}.formgrid{grid-template-columns:1fr 1fr;gap:14px 12px}.impactrow{grid-template-columns:130px 1fr 60px}.filters{width:100%}input[type=search]{flex:1;width:110px}.tablehead h3{margin:0}.scen-bottom{padding:12px}}
</style></head><body>
<header><div class="brand"><div class="brandmark">CS</div><div><h1>ChurnSense <span style="color:#3ed1bd">AI</span></h1><small>Customer Retention Intelligence</small></div></div><div class="head-meta">DỰ ÁN PORTFOLIO • PHẠM TRỌNG ĐẠT<br>Machine Learning · SQL · Data Analytics</div></header>
<main>
<div class="intro"><div><div class="eyebrow">Interactive machine learning demo · Offline</div><h2>Dự đoán nguy cơ khách hàng rời bỏ</h2><p>Phân tích hành vi sử dụng dịch vụ ngân hàng, nhận diện nhóm có nguy cơ và thử các tình huống giả định. Mô hình Logistic Regression được huấn luyện bằng Python trên dữ liệu mô phỏng.</p></div><div class="pill">● DEMO HOẠT ĐỘNG OFFLINE</div></div>
<div class="cards"><div class="stat"><div class="k">Khách hàng trong dữ liệu</div><strong id="nCustomers">–</strong><small>100% dữ liệu giả lập</small></div><div class="stat red"><div class="k">Khách hàng nguy cơ cao</div><strong id="highCustomers">–</strong><small>Xác suất dự đoán ≥ 50%</small></div><div class="stat accent"><div class="k">ROC-AUC (tập test)</div><strong id="auc">–</strong><small>Đánh giá trên 300 mẫu giữ lại</small></div><div class="stat"><div class="k">Độ chính xác (test)</div><strong id="accuracy">–</strong><small>Ngưỡng dự đoán 50%</small></div></div>
<div class="layout"><section class="panel"><div class="panelhead"><h3>Phân phối xác suất rời bỏ</h3><span class="sub">Tất cả 1.200 khách hàng</span></div><div class="bars" id="histogram"></div><div class="footnote">Mỗi cột đại diện một khoảng xác suất. Điểm càng cao thể hiện nguy cơ rời bỏ theo mô hình mô phỏng càng lớn.</div></section>
<section class="panel"><div class="panelhead"><h3>Yếu tố ảnh hưởng đến mô hình</h3><span class="sub">Hệ số chuẩn hóa</span></div><div class="impact" id="impacts"></div><div class="footnote">Hệ số dương làm tăng log-odds rời bỏ, hệ số âm làm giảm. Đây là mối liên hệ của mô hình, không chứng minh quan hệ nhân quả.</div></section></div>
<section class="panel scenario"><div class="panelhead"><div><h3>Thử mô hình AI với một khách hàng giả định</h3><div class="sub">Kéo thanh trượt để thấy kết quả cập nhật ngay, không cần Python hoặc kết nối mạng.</div></div><span class="pill">What-if simulation</span></div><div class="formgrid" id="sliders"></div><div class="scen-bottom"><div class="scoreline"><div><div class="scorebig" id="scenarioScore">–</div><div class="level" id="scenarioLabel"></div></div><div class="meter"><span id="scenarioMeter" style="width:0%"></span></div></div><div class="actions"><button class="alt" onclick="loadExample(true)">Thử nguy cơ cao</button><button onclick="loadExample(false)">Mặc định</button></div></div><div class="sub" style="margin-top:9px" id="scenarioNotes"></div></section>
<section class="panel tablepanel"><div class="tablehead"><div><h3>Danh sách khách hàng minh họa</h3><div class="sub">Nhấn một dòng để đưa đặc điểm khách hàng vào phần thử mô hình.</div></div><div class="filters"><input type="search" id="search" placeholder="Tìm mã khách hàng..." oninput="renderTable()"><select id="riskFilter" onchange="renderTable()"><option value="all">Mọi mức rủi ro</option><option value="high">Chỉ nguy cơ cao</option><option value="low">Chỉ nguy cơ thấp</option></select><button onclick="exportFilteredCsv()">Xuất CSV đang lọc</button></div></div><div class="scroll"><table><thead><tr><th>Mã khách hàng</th><th>Giao dịch/tháng</th><th>Đăng nhập/30 ngày</th><th>Ngày không hoạt động</th><th>Khiếu nại</th><th>Nguy cơ</th><th>Điểm AI</th></tr></thead><tbody id="rows"></tbody></table></div><div class="below"><span id="tableCounter"></span><span>Hiển thị tối đa 12 dòng • Sắp theo xác suất giảm dần</span></div></section>
<div class="alert"><strong>Minh bạch về dữ liệu:</strong> Đây là dự án minh họa phục vụ học tập/portfolio. Toàn bộ 1.200 hồ sơ và nhãn rời bỏ đều được tạo nhân tạo, không sử dụng thông tin khách hàng thật. Không áp dụng mô hình này để đưa ra quyết định tài chính hoặc chăm sóc khách hàng thực tế khi chưa được đánh giá trên dữ liệu có kiểm soát.</div>
<footer>ChurnSense AI · Portfolio demonstration · Python + scikit-learn (training) + JavaScript (offline inference) · Tài liệu và mã nguồn trong project ZIP.</footer>
</main>
<script>
const DATA=__DATA__;
const PARAMS=__PARAMS__;
const METRICS=__METRICS__;
const LABELS={tenure_months:'Thời gian gắn bó (tháng)',monthly_transactions:'Giao dịch / tháng',avg_balance_million_vnd:'Số dư TB (triệu đồng)',app_login_days_30d:'Ngày dùng app / 30 ngày',complaints_90d:'Khiếu nại / 90 ngày',product_count:'Số sản phẩm',digital_usage_pct:'Sử dụng kênh số (%)',inactive_days:'Ngày không hoạt động'};
const SETTINGS=[['tenure_months',1,96,1],['monthly_transactions',0,65,1],['avg_balance_million_vnd',0,250,1],['app_login_days_30d',0,30,1],['complaints_90d',0,6,1],['product_count',1,6,1],['digital_usage_pct',0,100,1],['inactive_days',0,60,1]];
const DEFAULT={tenure_months:24,monthly_transactions:16,avg_balance_million_vnd:18,app_login_days_30d:12,complaints_90d:0,product_count:2,digital_usage_pct:55,inactive_days:15};
const HIGH={tenure_months:7,monthly_transactions:3,avg_balance_million_vnd:3,app_login_days_30d:2,complaints_90d:3,product_count:1,digital_usage_pct:15,inactive_days:48};
let current={...DEFAULT}; let activeRows=[];
function formatNumber(x){return Number(x).toLocaleString('vi-VN')}
function score(row){let z=PARAMS.intercept;PARAMS.features.forEach((f,i)=>{z+=PARAMS.coefficients[i]*((Number(row[f])-PARAMS.means[i])/PARAMS.scales[i]);});return 1/(1+Math.exp(-z));}
function buildSliders(){document.getElementById('sliders').innerHTML=SETTINGS.map(([name,min,max,step])=>`<div class="field"><div class="fieldlabel"><span>${LABELS[name]}</span><span id="v_${name}" class="fieldval">${current[name]}</span></div><input aria-label="${LABELS[name]}" type="range" id="i_${name}" min="${min}" max="${max}" step="${step}" value="${current[name]}" oninput="onSlide('${name}',this.value)"></div>`).join('');renderScore();}
function onSlide(name,val){current[name]=Number(val);document.getElementById('v_'+name).textContent=val;renderScore();}
function renderScore(){const p=score(current),pct=Math.round(p*100);document.getElementById('scenarioScore').textContent=pct+'%';document.getElementById('scenarioMeter').style.width=pct+'%';document.getElementById('scenarioMeter').style.background=p>=.5?'#d35b53':'#168d82';document.getElementById('scenarioLabel').textContent=(p>=.5?'Nguy cơ cao':'Nguy cơ thấp')+' • Ngưỡng 50%';const best=PARAMS.features.map((f,i)=>({f,contrib:PARAMS.coefficients[i]*((current[f]-PARAMS.means[i])/PARAMS.scales[i])})).sort((a,b)=>b.contrib-a.contrib);document.getElementById('scenarioNotes').textContent='Tác động tăng rủi ro lớn nhất trong tình huống này: '+best.slice(0,2).map(x=>LABELS[x.f].toLowerCase()).join(', ')+'.';}
function loadExample(high){current={...(high?HIGH:DEFAULT)}; SETTINGS.forEach(([f])=>{document.getElementById('i_'+f).value=current[f];document.getElementById('v_'+f).textContent=current[f];});renderScore();document.querySelector('.scenario').scrollIntoView({behavior:'smooth',block:'center'});}
function loadCustomer(id){const item=DATA.find(x=>x.customer_id===id);if(!item)return;current={...item};SETTINGS.forEach(([f])=>{document.getElementById('i_'+f).value=current[f];document.getElementById('v_'+f).textContent=current[f];});renderScore();document.querySelector('.scenario').scrollIntoView({behavior:'smooth',block:'start'});}
function initHistogram(){let counts=Array(5).fill(0);for(const row of DATA){counts[Math.min(4,Math.floor(row.risk_score*5))]++;}const mx=Math.max(...counts);document.getElementById('histogram').innerHTML=counts.map((n,i)=>`<div class="barcol"><b>${n}</b><div class="bar" style="height:${Math.round(100*n/mx)}%"></div><span>${i*20}–${i*20+20}%</span></div>`).join('');}
function initImpact(){const imp=PARAMS.features.map((f,i)=>({f,c:PARAMS.coefficients[i]})).sort((a,b)=>Math.abs(b.c)-Math.abs(a.c));const m=Math.max(...imp.map(x=>Math.abs(x.c)));document.getElementById('impacts').innerHTML=imp.map(x=>`<div class="impactrow"><span class="name">${LABELS[x.f]}</span><div class="track"><div class="fill ${x.c>0?'plus':''}" style="width:${Math.abs(x.c)/m*100}%"></div></div><small>${x.c>0?'+':''}${x.c.toFixed(2)}</small></div>`).join('');}
function getFiltered(){let q=document.getElementById('search').value.trim().toUpperCase(),mode=document.getElementById('riskFilter').value;return DATA.filter(x=>(!q||x.customer_id.includes(q))&&(mode==='all'||(mode==='high'?x.risk_score>=.5:x.risk_score<.5))).sort((a,b)=>b.risk_score-a.risk_score);}
function renderTable(){activeRows=getFiltered();document.getElementById('rows').innerHTML=activeRows.slice(0,12).map(x=>{const high=x.risk_score>=.5;const pct=Math.round(x.risk_score*100);return `<tr onclick="loadCustomer('${x.customer_id}')" style="cursor:pointer"><td style="font-weight:750">${x.customer_id}</td><td>${x.monthly_transactions}</td><td>${x.app_login_days_30d}</td><td>${x.inactive_days}</td><td>${x.complaints_90d}</td><td><span class="tag ${high?'high':'low'}">${high?'Cao':'Thấp'}</span></td><td><div style="font-weight:750">${pct}%</div><div class="barcell barbg"><span class="${high?'high':''}" style="width:${pct}%"></span></div></td></tr>`;}).join('');document.getElementById('tableCounter').textContent='Tìm thấy '+formatNumber(activeRows.length)+' khách hàng mô phỏng';}
function exportFilteredCsv(){const names=['customer_id',...PARAMS.features,'churn_next_30d','risk_score'];const esc=v=>'"'+String(v).replaceAll('"','""')+'"';const content='\uFEFF'+[names.join(','),...activeRows.map(x=>names.map(k=>esc(x[k])).join(','))].join('\r\n');const blob=new Blob([content],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='ChurnSense_filtered.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);}
function init(){document.getElementById('nCustomers').textContent=formatNumber(DATA.length);document.getElementById('highCustomers').textContent=formatNumber(DATA.filter(x=>x.risk_score>=.5).length);document.getElementById('auc').textContent=METRICS.roc_auc_test.toFixed(3).replace('.',',');document.getElementById('accuracy').textContent=(METRICS.accuracy_test_at_0_5*100).toFixed(1).replace('.',',')+'%';buildSliders();initHistogram();initImpact();renderTable();}init();
</script></body></html>'''
html=html.replace('__DATA__',json.dumps(rows,ensure_ascii=False,separators=(',',':'))).replace('__PARAMS__',json.dumps(params,ensure_ascii=False,separators=(',',':'))).replace('__METRICS__',json.dumps(metrics,ensure_ascii=False,separators=(',',':')))
(root/'ChurnSense_Demo.html').write_text(html,encoding='utf-8')
print('Created HTML:',round((root/'ChurnSense_Demo.html').stat().st_size/1024,1),'KiB')
